import csv, io

data = 'id,name,qty\n1,Ada,3\n2,"Bob"x,5\n3,Cy\n4,Di,4,EXTRA\n'
errors, good = [], []
reader = csv.DictReader(io.StringIO(data), strict=True, restkey="_extra")
while True:
    try:
        row = next(reader)
    except StopIteration:
        break
    except csv.Error as e:
        errors.append((reader.line_num, f"syntax: {e}"))
        continue
    if row.get("_extra") or None in row.values():
        errors.append((reader.line_num, "wrong number of fields"))
    else:
        good.append(row)

print([r["id"] for r in good])  # ['1']
for line, msg in errors:
    print(line, msg)
# 2 syntax: ',' expected after '"'   (line_num = last line fully read)
# 4 wrong number of fields
# 5 wrong number of fields

import csv, io, time

text = "id,name,qty\n" + "".join(f"{i},user{i},{i % 7}\n" for i in range(300_000))

def timed(label, fn):
    t = time.perf_counter(); result = fn()
    print(f"{label:12} {time.perf_counter() - t:.3f}s  total={result}")

def with_dictreader():
    return sum(int(r["qty"]) for r in csv.DictReader(io.StringIO(text)))

def with_reader():
    rows = csv.reader(io.StringIO(text))
    qty = next(rows).index("qty")
    return sum(int(r[qty]) for r in rows)

timed("DictReader", with_dictreader)   # e.g. DictReader   0.250s  total=899997
timed("reader", with_reader)           # e.g. reader       0.110s  total=899997
